-- ============================================================
-- RAILWAY MANAGEMENT SYSTEM (SQLite)
-- Run:  sqlite3 railway.db < railway.sql
-- ============================================================
PRAGMA foreign_keys = ON;

-- ---------- 1. SCHEMA ----------
CREATE TABLE stations (
    station_id   INTEGER PRIMARY KEY,
    code         TEXT NOT NULL UNIQUE,
    name         TEXT NOT NULL,
    city         TEXT NOT NULL
);

CREATE TABLE trains (
    train_id     INTEGER PRIMARY KEY,
    train_no     TEXT NOT NULL UNIQUE,
    name         TEXT NOT NULL,
    train_type   TEXT CHECK (train_type IN ('Rajdhani','Shatabdi','Express','Superfast'))
);

-- Ordered stops of each train
CREATE TABLE train_routes (
    train_id     INTEGER NOT NULL REFERENCES trains(train_id),
    station_id   INTEGER NOT NULL REFERENCES stations(station_id),
    stop_order   INTEGER NOT NULL,
    arrival      TEXT,            -- HH:MM (NULL at origin)
    departure    TEXT,            -- HH:MM (NULL at terminus)
    distance_km  INTEGER NOT NULL, -- cumulative from origin
    PRIMARY KEY (train_id, stop_order),
    UNIQUE (train_id, station_id)
);

CREATE TABLE classes (
    class_id     INTEGER PRIMARY KEY,
    code         TEXT NOT NULL UNIQUE,   -- SL, 3A, 2A, 1A
    description  TEXT,
    fare_per_km  REAL NOT NULL
);

CREATE TABLE train_classes (
    train_id     INTEGER NOT NULL REFERENCES trains(train_id),
    class_id     INTEGER NOT NULL REFERENCES classes(class_id),
    total_seats  INTEGER NOT NULL CHECK (total_seats > 0),
    PRIMARY KEY (train_id, class_id)
);

-- Seats left for a train / date / class
CREATE TABLE seat_availability (
    train_id      INTEGER NOT NULL,
    journey_date  TEXT NOT NULL,
    class_id      INTEGER NOT NULL,
    available     INTEGER NOT NULL CHECK (available >= 0),
    PRIMARY KEY (train_id, journey_date, class_id),
    FOREIGN KEY (train_id, class_id) REFERENCES train_classes(train_id, class_id)
);

CREATE TABLE passengers (
    passenger_id INTEGER PRIMARY KEY,
    name         TEXT NOT NULL,
    age          INTEGER CHECK (age BETWEEN 0 AND 120),
    gender       TEXT CHECK (gender IN ('M','F','O')),
    phone        TEXT,
    email        TEXT UNIQUE
);

CREATE TABLE bookings (
    pnr           INTEGER PRIMARY KEY,
    passenger_id  INTEGER NOT NULL REFERENCES passengers(passenger_id),
    train_id      INTEGER NOT NULL,
    class_id      INTEGER NOT NULL,
    journey_date  TEXT NOT NULL,
    from_station  INTEGER NOT NULL REFERENCES stations(station_id),
    to_station    INTEGER NOT NULL REFERENCES stations(station_id),
    fare          REAL NOT NULL,
    status        TEXT NOT NULL DEFAULT 'CONFIRMED'
                  CHECK (status IN ('CONFIRMED','WAITLIST','CANCELLED')),
    booked_at     TEXT NOT NULL DEFAULT (datetime('now')),
    CHECK (from_station <> to_station),
    FOREIGN KEY (train_id, class_id) REFERENCES train_classes(train_id, class_id)
);

CREATE TABLE payments (
    payment_id   INTEGER PRIMARY KEY,
    pnr          INTEGER NOT NULL REFERENCES bookings(pnr),
    amount       REAL NOT NULL,
    mode         TEXT CHECK (mode IN ('UPI','CARD','NETBANKING','CASH')),
    paid_at      TEXT NOT NULL DEFAULT (datetime('now')),
    is_refund    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE audit_log (
    log_id     INTEGER PRIMARY KEY,
    pnr        INTEGER,
    action     TEXT,
    logged_at  TEXT DEFAULT (datetime('now'))
);

CREATE INDEX idx_bookings_passenger ON bookings(passenger_id);
CREATE INDEX idx_bookings_train_date ON bookings(train_id, journey_date);

-- ---------- 2. TRIGGERS ----------
-- Confirmed booking -> reduce seats
CREATE TRIGGER trg_booking_confirm
AFTER INSERT ON bookings
WHEN NEW.status = 'CONFIRMED'
BEGIN
    UPDATE seat_availability
       SET available = available - 1
     WHERE train_id = NEW.train_id AND class_id = NEW.class_id
       AND journey_date = NEW.journey_date;
    INSERT INTO audit_log(pnr, action) VALUES (NEW.pnr, 'BOOKED');
END;

-- Cancellation -> free the seat, record 80% refund
CREATE TRIGGER trg_booking_cancel
AFTER UPDATE OF status ON bookings
WHEN OLD.status = 'CONFIRMED' AND NEW.status = 'CANCELLED'
BEGIN
    UPDATE seat_availability
       SET available = available + 1
     WHERE train_id = NEW.train_id AND class_id = NEW.class_id
       AND journey_date = NEW.journey_date;
    INSERT INTO payments(pnr, amount, mode, is_refund)
         VALUES (NEW.pnr, ROUND(NEW.fare * 0.8, 2), 'UPI', 1);
    INSERT INTO audit_log(pnr, action) VALUES (NEW.pnr, 'CANCELLED');
END;

-- ---------- 3. VIEWS ----------
-- Fare is computed from distance between the two stops
CREATE VIEW v_fare_calc AS
SELECT t.train_id, tc.class_id, a.station_id AS from_station, b.station_id AS to_station,
       (b.distance_km - a.distance_km) AS km,
       ROUND((b.distance_km - a.distance_km) * c.fare_per_km, 2) AS fare
FROM trains t
JOIN train_routes a ON a.train_id = t.train_id
JOIN train_routes b ON b.train_id = t.train_id AND b.stop_order > a.stop_order
JOIN train_classes tc ON tc.train_id = t.train_id
JOIN classes c ON c.class_id = tc.class_id;

CREATE VIEW v_ticket AS
SELECT b.pnr, p.name AS passenger, t.train_no, t.name AS train, c.code AS class,
       fs.name AS from_stn, ts.name AS to_stn, b.journey_date, b.fare, b.status
FROM bookings b
JOIN passengers p ON p.passenger_id = b.passenger_id
JOIN trains t     ON t.train_id = b.train_id
JOIN classes c    ON c.class_id = b.class_id
JOIN stations fs  ON fs.station_id = b.from_station
JOIN stations ts  ON ts.station_id = b.to_station;

