-- Payments for every booking
INSERT INTO payments(pnr, amount, mode)
SELECT pnr, fare, CASE pnr % 3 WHEN 0 THEN 'UPI' WHEN 1 THEN 'CARD' ELSE 'NETBANKING' END FROM bookings;

-- One cancellation (fires refund + seat release trigger)
UPDATE bookings SET status = 'CANCELLED' WHERE pnr = 4;

